package io.knowledgebrain.learning;
import java.util.*;import java.time.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.publicroadmap.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class PublicRoadmapStoreIntegrationTest {
 PublicRoadmapStore store;JdbcTemplate sql;PGSimpleDataSource ds;UUID space,author,reviewer;String trace="a".repeat(32);
 @BeforeEach void setup(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();store=new PublicRoadmapStore(ds,Clock.systemUTC());sql=new JdbcTemplate(ds);var ids=new UuidV7(Clock.systemUTC());space=ids.next();author=ids.next();reviewer=ids.next();}
 static RoadmapGraph.Edit graph(){return new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","First","A"),new RoadmapGraph.NodeEdit("new:b","Second","B")),List.of(new RoadmapGraph.EdgeEdit("new:e","PREREQUISITE_OF","new:a","new:b")));}
 static RoadmapGraph.Edit edit(PublicRoadmapStore.Roadmap v){return new RoadmapGraph.Edit(v.nodes().stream().map(n->new RoadmapGraph.NodeEdit(n.nodeId().toString(),n.title(),n.description())).toList(),v.edges().stream().map(e->new RoadmapGraph.EdgeEdit(e.edgeId().toString(),e.kind(),e.sourceNodeId().toString(),e.targetNodeId().toString())).toList());}
 PublicRoadmapStore.Proposal submit(){return store.submit(space,author,null,0,"Public graph","Explicit public body","Reason",graph(),trace);}
 PublicRoadmapStore.Roadmap publish(){var p=submit();store.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);store.merge(space,p.contributionId(),reviewer,2,trace);return store.get(space,p.roadmapId());}
 void status(int expected,org.junit.jupiter.api.function.Executable action){assertEquals(expected,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 int events(UUID id){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Integer.class,id);}
 @Test void immutableExplicitProposalPublishesOnlyAfterReviewWithOwnIdsAndExactEnvelopes()throws Exception{
  var privateStore=new RoadmapStore(ds,Clock.systemUTC());var secret=privateStore.create(author,author,"SECRET private","PRIVATE progress/evidence stay private",trace);
  var p=submit();assertEquals(7,p.roadmapId().version());assertEquals(1,events(p.contributionId()));assertTrue(store.list(space,null,20).items().isEmpty());status(404,()->store.get(space,p.roadmapId()));status(403,()->store.review(space,p.contributionId(),author,1,"APPROVED","Self",trace));status(409,()->store.merge(space,p.contributionId(),reviewer,1,trace));
  var approved=store.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);assertEquals(2,approved.version());assertTrue(store.list(space,null,20).items().isEmpty());status(403,()->store.merge(space,p.contributionId(),author,2,trace));store.merge(space,p.contributionId(),reviewer,2,trace);
  var v=store.get(space,p.roadmapId());assertEquals("PUBLIC",v.visibility());assertEquals("REVIEWED",v.verification());assertEquals(p.graph().nodes(),v.nodes());assertEquals(p.graph().edges(),v.edges());assertEquals(1,v.version());assertEquals(secret,privateStore.get(author,secret.roadmapId()));status(404,()->store.get(author,p.roadmapId()));assertEquals(3,events(p.contributionId()));assertEquals(1,events(v.roadmapId()));assertEquals(List.of("APPROVED","MERGED"),store.reviews(space,p.contributionId()).stream().map(PublicRoadmapStore.Review::decision).toList());
  var wire=sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.roadmapId());var envelope=PublicRoadmapEnvelopeV1.parseFrom(wire);var body=PublicRoadmapChangedV1.parseFrom(envelope.getPayload());assertEquals(trace,envelope.getTraceId());assertEquals(space.toString(),envelope.getSpaceId());assertEquals(reviewer.toString(),envelope.getActorId());assertEquals("PublicRoadmapPublished",envelope.getEventType());assertEquals("PublicRoadmap",envelope.getAggregateType());assertEquals(2,body.getSnapshot().getNodesCount());assertEquals(store.history(space,v.roadmapId(),Long.MAX_VALUE,1).getFirst().revisionId().toString(),body.getRevisionId());assertEquals(v,store.history(space,v.roadmapId(),Long.MAX_VALUE,1).getFirst().snapshot());
 }
 @Test void staleApprovedUpdateNeverOverwritesAndOriginalGraphAndAuditRemain(){var original=publish();var first=store.submit(space,author,original.roadmapId(),1,"First","","A",edit(original),trace);var second=store.submit(space,author,original.roadmapId(),1,"Second","","B",edit(original),trace);for(var p:List.of(first,second))store.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);store.merge(space,first.contributionId(),reviewer,2,trace);status(412,()->store.merge(space,second.contributionId(),reviewer,2,trace));assertEquals("APPROVED",store.proposal(space,second.contributionId()).state());assertEquals(2,events(second.contributionId()));var current=store.get(space,original.roadmapId());assertEquals("First",current.title());assertEquals(original.nodes(),current.nodes());assertEquals(original,store.history(space,current.roadmapId(),2,1).getFirst().snapshot());status(412,()->store.submit(space,author,original.roadmapId(),1,"Stale","","Reason",edit(original),trace));}
 @Test void competingReviewHasOneWinnerAndRejectIsTerminal()throws Exception{var p=submit();try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var barrier=new java.util.concurrent.CyclicBarrier(2);var calls=new ArrayList<java.util.concurrent.Future<Boolean>>();for(String decision:List.of("APPROVED","REJECTED"))calls.add(pool.submit(()->{barrier.await();try{store.review(space,p.contributionId(),reviewer,1,decision,"Checked",trace);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));assertNotEquals(calls.get(0).get(),calls.get(1).get());}assertEquals(1,store.reviews(space,p.contributionId()).size());var rejected=submit();store.review(space,rejected.contributionId(),reviewer,1,"REJECTED","Revise graph",trace);status(409,()->store.merge(space,rejected.contributionId(),reviewer,2,trace));assertEquals(2,events(rejected.contributionId()));}
 @Test void failedContributionOutboxRollsBackCanonicalRevisionReviewAndState(){var p=submit();store.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);String constraint="public_roadmap_test_"+p.contributionId().toString().replace("-","");sql.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+" CHECK (aggregateid <> '"+p.contributionId()+"'::uuid OR type <> 'RoadmapContributionMerged') NOT VALID");try{assertThrows(RuntimeException.class,()->store.merge(space,p.contributionId(),reviewer,2,trace));status(404,()->store.get(space,p.roadmapId()));assertEquals("APPROVED",store.proposal(space,p.contributionId()).state());assertEquals(1,store.reviews(space,p.contributionId()).size());assertEquals(0,events(p.roadmapId()));}finally{sql.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}}
 @Test void rejectsPrivateIdsRetiredPublicNodesCyclesOversizeAndSpoofedIds(){var original=publish();var removed=new RoadmapGraph.Edit(List.of(),List.of());var p=store.submit(space,author,original.roadmapId(),1,"Empty","","Explicit removal",removed,trace);store.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);store.merge(space,p.contributionId(),reviewer,2,trace);status(400,()->store.submit(space,author,original.roadmapId(),2,"Restore","","No retired IDs",edit(original),trace));status(400,()->store.submit(space,author,null,0,"Private IDs","","Denied",edit(original),trace));status(404,()->store.submit(space,author,author,1,"Private target","","Denied",graph(),trace));var nodes=new ArrayList<RoadmapGraph.NodeEdit>();var edges=new ArrayList<RoadmapGraph.EdgeEdit>();for(int n=0;n<100;n++)nodes.add(new RoadmapGraph.NodeEdit("new:n"+n,"가".repeat(200),"\"".repeat(2048)));outer:for(int i=0;i<100;i++)for(int j=i+1;j<100;j++){edges.add(new RoadmapGraph.EdgeEdit("new:e"+edges.size(),"RELATED_TO","new:n"+i,"new:n"+j));if(edges.size()==500)break outer;}int before=store.proposals(space,null,100).items().size();status(400,()->store.submit(space,author,null,0,"Big","\"".repeat(32768),"Reason",new RoadmapGraph.Edit(nodes,edges),trace));assertEquals(before,store.proposals(space,null,100).items().size());}
 @Test void boundedCatalogAndRevisionPagination(){for(int i=0;i<22;i++)submit();var first=store.proposals(space,null,20);assertEquals(20,first.items().size());assertEquals(2,store.proposals(space,first.nextAfter(),20).items().size());assertTrue(store.proposals(author,null,20).items().isEmpty());var v=publish();for(int i=1;i<=6;i++){var p=store.submit(space,author,v.roadmapId(),i,"v"+(i+1),"","Update",edit(v),trace);store.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);store.merge(space,p.contributionId(),reviewer,2,trace);}assertEquals(List.of(7L,6L,5L,4L,3L),store.history(space,v.roadmapId(),Long.MAX_VALUE,5).stream().map(PublicRoadmapStore.Revision::version).toList());assertEquals(List.of(2L,1L),store.history(space,v.roadmapId(),3,5).stream().map(PublicRoadmapStore.Revision::version).toList());}
}
